export async function seedProductionContactInsightsIfNeeded() {
  const [{ total }] = await db.select({ total: sql<number>`count(*)::int` }).from(contactInsightsTable);
  const expectedUniqueCount = CONTACT_INSIGHTS_BY_CONTACT.reduce(
    (count, group) => count + new Set(group.insights.map((insight: any) => insight.url)).size,
    0,
  );
  if (total >= expectedUniqueCount) {
    console.log(`Contact insights already synced (${total} rows). Skipping.`);
    return;
  }

  console.log(`Syncing contact insights (${total} existing, 4991 total)...`);

  let inserted = 0, skipped = 0;

  for (const group of CONTACT_INSIGHTS_BY_CONTACT) {
    // Look up contact in production by email, fallback to first+last name
    let contact: { id: number } | undefined;
    if (group.email) {
      const found = await db.select({ id: contactsTable.id }).from(contactsTable)
        .where(eq(contactsTable.email, group.email)).limit(1);
      contact = found[0];
    }
    if (!contact) {
      const found = await db.select({ id: contactsTable.id }).from(contactsTable)
        .where(and(eq(contactsTable.firstName, group.firstName), eq(contactsTable.lastName, group.lastName)))
        .limit(1);
      contact = found[0];
    }
    if (!contact) { skipped += group.insights.length; continue; }

    // Skip if this contact already has insights
    const [{ existing }] = await db.select({ existing: sql<number>`count(*)::int` })
      .from(contactInsightsTable).where(eq(contactInsightsTable.contactId, contact.id));
    if (existing > 0) { skipped += group.insights.length; continue; }

    const uniqueInsights = [...new Map(group.insights.map((insight: any) => [insight.url, insight])).values()] as any[];
    const rows = await db.insert(contactInsightsTable).values(
      uniqueInsights.map((i: any) => ({
        contactId: contact!.id,
        title: i.title,
        url: i.url || "",
        source: i.source || null,
        mediaType: i.mediaType || null,
        description: i.description || null,
        publishedDate: i.publishedDate || null,
        category: i.category || "personal",
      }))
    ).onConflictDoNothing().returning({ id: contactInsightsTable.id });
    inserted += rows.length;
    skipped += uniqueInsights.length - rows.length;
  }
  console.log(`Contact insights sync complete: ${inserted} inserted, ${skipped} skipped.`);
}
